from lib import *
PAGE = page('trust-imprint',
 ("Imprint and legal notice", "Mentions légales", "الإشعار القانوني"),
 ("Who publishes W5D, how to reach the publisher, what is and is not yet registered, who hosts and processes data, and which law applies.",
  "Qui publie W5D, comment joindre l’éditeur, ce qui est et n’est pas encore enregistré, qui héberge et traite les données, et quel droit s’applique.",
  "من ينشر W5D، وكيف تتصل بالناشر، وما سُجّل وما لم يُسجَّل بعدُ، ومن يستضيف البيانات ويعالجها، وأي قانون يُطبَّق."),
 [
 hero('im-hero', ("Who is behind **this site.**", "Qui est derrière **ce site.**", "من يقف وراء **هذا الموقع.**"),
  ("A legal notice should tell you who publishes a site, where to reach them and what they are legally. This one also says what does not exist yet, because an empty field that looks complete is worse than a missing one.",
   "Des mentions légales doivent dire qui publie un site, où le joindre et ce qu’il est juridiquement. Celles-ci disent aussi ce qui n’existe pas encore, car un champ vide qui paraît complet est pire qu’un champ absent.",
   "ينبغي أن يقول الإشعار القانوني من ينشر الموقع وكيف يُتصل به وما صفته القانونية. وهذا الإشعار يقول أيضًا ما لم يوجد بعد، لأن حقلًا فارغًا يبدو مكتملًا أسوأ من حقل غائب."),
  ("Imprint", "Mentions légales", "الإشعار القانوني"),
  [(("Write to the publisher", "Écrire à l’éditeur", "راسل الناشر"), '/contact/', 'peak', True)]),
 prose('im-who', ("The publisher", "L’éditeur", "الناشر"), [
  ("This site is published under the name {{ company.brand }}, operated from {{ company.country }}, since {{ company.since }}. The names W5D, MetaX Academy and the W5D logo are names used by {{ company.brand }}. The person responsible for the publication is the founder and owner, who is named on the [team page](/team/) and who answers for every page under the rules of the [editorial policy](/trust/editorial/).",
   "Ce site est publié sous le nom {{ company.brand }}, exploité depuis la {{ company.country }}, depuis {{ company.since }}. Les noms W5D, MetaX Academy et le logo W5D sont des noms utilisés par {{ company.brand }}. La personne responsable de la publication est le fondateur et propriétaire, nommé sur la [page de l’équipe](/team/), qui répond de chaque page selon les règles de la [politique éditoriale](/trust/editorial/).",
   "يُنشر هذا الموقع باسم {{ company.brand }} ويُدار من {{ company.country }} منذ {{ company.since }}. وأسماء W5D وMetaX Academy وشعار W5D أسماء تستخدمها {{ company.brand }}. والمسؤول عن النشر هو المؤسس والمالك المذكور في [صفحة الفريق](/team/)، وهو يتحمل مسؤولية كل صفحة وفق قواعد [السياسة التحريرية](/trust/editorial/)."),
  ("W5D is a programme, and a young one. Part of what the site describes, such as the network of certified experts and the registry activation, is a plan with dates, not a finished fact. The [status page](/status/) shows, with live figures, how far each element has gone. We ask you to read this notice together with that page.",
   "W5D est un programme, et un jeune programme. Une partie de ce que décrit le site, comme le réseau d’experts certifiés et l’activation du registre, est un plan avec des dates, non un fait accompli. La [page de statut](/status/) montre, avec des chiffres en direct, où en est chaque élément. Nous vous demandons de lire cet avis avec cette page.",
   "W5D برنامج، وهو برنامج فتيّ. وجزء مما يصفه الموقع، كشبكة الخبراء المعتمدين وتفعيل السجل، خطة بمواعيد لا واقع منجز. وتُظهر [صفحة الحالة](/status/) بأرقام حية مدى تقدم كل عنصر. ونرجو أن تقرأ هذا الإشعار مع تلك الصفحة.")]),
 table('im-id', ("Identification, field by field", "Identification, champ par champ", "التعريف حقلًا حقلًا"),
  [("Field", "Champ", "الحقل"), ("What this notice says", "Ce que disent ces mentions", "ما يقوله هذا الإشعار")],
  [[("Trading name", "Nom commercial", "الاسم التجاري"), ("{{ company.brand }}", "{{ company.brand }}", "{{ company.brand }}")],
   [("Country of operation", "Pays d’exploitation", "بلد النشاط"), ("{{ company.country }}", "{{ company.country }}", "{{ company.country }}")],
   [("Legal form", "Forme juridique", "الشكل القانوني"), ("Shown in the footer of every page and kept in step with reality. At the last review ({{ dates.as_of }}) the registration was still pending, and the site is run by its founder.", "Indiquée en pied de chaque page et tenue en phase avec la réalité. À la dernière revue ({{ dates.as_of }}), l’immatriculation était encore en cours et le site est exploité par son fondateur.", "تظهر في تذييل كل صفحة وتُبقى مطابقة للواقع. وعند آخر مراجعة ({{ dates.as_of }}) كان التسجيل لا يزال قيد الإنجاز ويديره مؤسسه.")],
   [("Company registry number", "Numéro au registre des entreprises", "رقم السجل التجاري"), ("Not shown, because none has been issued at the last review. We do not print a placeholder number. It is added here, with its date, when it exists.", "Non indiqué, car aucun n’avait été délivré à la dernière revue. Nous n’affichons pas de numéro fictif. Il sera ajouté ici, avec sa date, lorsqu’il existera.", "غير مذكور لأنه لم يصدر أي رقم عند آخر مراجعة. ولا نطبع رقمًا وهميًا. وسيُضاف هنا بتاريخه حين يوجد.")],
   [("Tax identifier (matricule fiscal)", "Identifiant fiscal (matricule fiscal)", "المعرّف الجبائي"), ("Not shown, for the same reason. Until it exists the business cannot issue tax invoices, which is why some payment channels are closed. See the [status page](/status/).", "Non indiqué, pour la même raison. Tant qu’il n’existe pas, l’entreprise ne peut pas émettre de factures fiscales, c’est pourquoi certains canaux de paiement sont fermés. Voir la [page de statut](/status/).", "غير مذكور للسبب نفسه. وإلى أن يوجد لا يستطيع النشاط إصدار فواتير جبائية، ولهذا أُغلقت بعض قنوات الدفع. انظر [صفحة الحالة](/status/).")],
   [("Postal address", "Adresse postale", "العنوان البريدي"), ("Not published at this stage. Formal notices can be sent through the contact form or by e-mail, and a postal address is given in reply when a formal notice requires one.", "Non publiée à ce stade. Les notifications formelles peuvent être envoyées par le formulaire de contact ou par e-mail, et une adresse postale est communiquée en réponse lorsqu’une notification formelle l’exige.", "غير منشور في هذه المرحلة. ويمكن إرسال الإشعارات الرسمية عبر نموذج الاتصال أو البريد، ونعطي عنوانًا بريديًا في الرد حين يتطلبه إشعار رسمي.")],
   [("Contact e-mail", "E-mail de contact", "البريد الإلكتروني"), ("{{ company.privacy_contact }}", "{{ company.privacy_contact }}", "{{ company.privacy_contact }}")],
   [("Opening hours", "Horaires", "ساعات العمل"), ("{{ company.hours }}", "{{ company.hours }}", "{{ company.hours }}")],
   [("Answer time", "Délai de réponse", "مدة الرد"), ("{{ company.response_days }} working days", "{{ company.response_days }} jours ouvrés", "{{ company.response_days }} أيام عمل")]],
  note=("This table is deliberately honest about gaps. When a registry number or a tax identifier is issued, this page is updated first and the footer wording changes with it.",
        "Ce tableau est volontairement honnête sur ses lacunes. Lorsqu’un numéro de registre ou un identifiant fiscal est délivré, cette page est mise à jour en premier et le libellé du pied de page change avec elle.",
        "هذا الجدول صريح عمدًا في شأن الفجوات. وحين يصدر رقم سجل أو معرّف جبائي تُحدَّث هذه الصفحة أولًا ويتغير نص التذييل معها.")),
 prose('im-why', ("Why we do not fill the gaps with placeholders", "Pourquoi nous ne comblons pas les vides avec des valeurs fictives", "لماذا لا نملأ الفجوات بقيم وهمية"), [
  ("A typical legal notice lists a registration number, a capital and an address. A site that has none of these yet might be tempted to print something that looks right. We do not, for three reasons. A false identifier can be checked in a registry in seconds, and the moment it is found false everything else on the site is doubted. A false identifier can mislead a buyer about who they are contracting with and what protection they have. And in many legal systems, including Tunisia’s, misrepresenting a legal identity is itself an offence, which is a risk we will not take on behalf of anyone.",
   "Des mentions légales typiques énumèrent un numéro d’immatriculation, un capital et une adresse. Un site qui n’a encore rien de tout cela pourrait être tenté d’afficher quelque chose qui a l’air juste. Nous ne le faisons pas, pour trois raisons. Un faux identifiant se vérifie dans un registre en quelques secondes, et dès qu’il est trouvé faux, tout le reste du site est mis en doute. Un faux identifiant peut tromper un acheteur sur la personne avec qui il contracte et sur la protection dont il dispose. Et dans de nombreux systèmes juridiques, dont celui de la Tunisie, présenter une fausse identité juridique est en soi une infraction, risque que nous ne prendrons pour personne.",
   "يعدّد الإشعار القانوني المعتاد رقم تسجيل ورأس مال وعنوانًا. وقد يُغري موقعًا لا يملك شيئًا من ذلك بعد أن يطبع ما يبدو صحيحًا. ونحن لا نفعل لثلاثة أسباب. فالمعرّف الزائف يمكن التحقق منه في سجل خلال ثوانٍ، وما إن يُكتشف زيفه حتى يُشكَّ في كل ما سواه. والمعرّف الزائف قد يضلل المشتري في من يتعاقد معه وما الحماية التي يملكها. وفي أنظمة قانونية كثيرة ومنها التونسي يُعدّ انتحال هوية قانونية مخالفة في ذاته، وهو خطر لن نتحمله نيابةً عن أحد."),
  ("What we do instead is say what is true. The site is run by its founder, the registration is in progress, the money you may be asked to pay is handled by the channels the [terms](/trust/terms/) describe, and every channel that needs a registered business is closed until the business is registered. You can see which channels are open and which are closed, with the reason, on the live [status page](/status/).",
   "Ce que nous faisons à la place, c’est dire ce qui est vrai. Le site est exploité par son fondateur, l’immatriculation est en cours, l’argent que l’on peut vous demander est traité par les canaux que décrivent les [conditions](/trust/terms/), et tout canal qui exige une entreprise immatriculée est fermé jusqu’à l’immatriculation. Vous pouvez voir quels canaux sont ouverts et lesquels sont fermés, avec la raison, sur la [page de statut](/status/) en direct.",
   "وما نفعله بدلًا من ذلك أن نقول الحقيقة. يديره مؤسسه، والتسجيل قيد الإنجاز، والمال الذي قد يُطلب منك دفعه تعالجه القنوات التي تصفها [الشروط](/trust/terms/)، وكل قناة تتطلب نشاطًا مسجلًا مغلقة حتى يتم التسجيل. ويمكنك رؤية القنوات المفتوحة والمغلقة مع السبب في [صفحة الحالة](/status/) الحية.")]),
 prose('im-host', ("Hosting, providers and where data goes", "Hébergement, prestataires et destination des données", "الاستضافة والمزودون ووجهة البيانات"), [
  ("The site runs as a PHP application with a local SQLite database. It is served from a hosting provider selected by the owner for the production site, and the name and country of that provider are given on written request through the [contact page](/contact/), because they can change with the hosting plan and we do not want a notice that becomes wrong when the plan changes. The list of the kinds of provider that receive personal data, and what each receives, is in the [privacy policy](/trust/privacy/). The cookies the site sets are listed one by one in the [cookie policy](/trust/cookies/).",
   "Le site fonctionne comme une application PHP avec une base de données SQLite locale. Il est servi par un hébergeur choisi par le propriétaire pour le site de production ; le nom et le pays de cet hébergeur sont communiqués sur demande écrite via la [page de contact](/contact/), car ils peuvent changer avec l’offre d’hébergement et nous ne voulons pas de mentions qui deviennent fausses quand l’offre change. La liste des catégories de prestataires qui reçoivent des données personnelles, et ce que chacun reçoit, figure dans la [politique de confidentialité](/trust/privacy/). Les cookies déposés par le site sont listés un par un dans la [politique de cookies](/trust/cookies/).",
   "يعمل الموقع تطبيق PHP بقاعدة بيانات SQLite محلية. ويُقدَّم من مزوّد استضافة يختاره المالك للموقع الإنتاجي، ويُعطى اسم هذا المزوّد وبلده عند الطلب الكتابي عبر [صفحة الاتصال](/contact/) لأنهما قد يتغيران بتغير خطة الاستضافة ولا نريد إشعارًا يصبح خاطئًا بتغيرها. وقائمة أصناف المزودين الذين يتلقون بيانات شخصية وما يتلقاه كل منهم في [سياسة الخصوصية](/trust/privacy/). وتُدرج الكوكيز التي يضعها الموقع واحدًا واحدًا في [سياسة الكوكيز](/trust/cookies/)."),
  ("The site does not load fonts, scripts or images from outside services to display a page. Optional measurement and advertising tools, if the owner ever enables them, load only after you accept them, and the payment providers you choose receive data only when you pay. If you want to know whether a specific provider has your data, use the procedure on the [data rights page](/trust/data-rights/); we answer in writing within {{ privacy.rights_days }} days.",
   "Le site ne charge pas de polices, de scripts ou d’images depuis des services extérieurs pour afficher une page. Les outils facultatifs de mesure et de publicité, si le propriétaire les active un jour, ne se chargent qu’après votre acceptation, et les prestataires de paiement que vous choisissez ne reçoivent des données que lorsque vous payez. Si vous voulez savoir si un prestataire précis détient vos données, suivez la procédure de la page [vos droits](/trust/data-rights/) ; nous répondons par écrit sous {{ privacy.rights_days }} jours.",
   "لا يحمّل الموقع خطوطًا أو سكربتات أو صورًا من خدمات خارجية لعرض صفحة. وأدوات القياس والإعلان الاختيارية، إن فعّلها المالك يومًا، لا تُحمَّل إلا بعد قبولك، ولا يتلقى مزودو الدفع الذين تختارهم بيانات إلا حين تدفع. وإن أردت معرفة هل لدى مزوّد بعينه بياناتك فاتبع الإجراء في صفحة [حقوقك](/trust/data-rights/)؛ ونجيب كتابةً خلال {{ privacy.rights_days }} يومًا.")]),
 prose('im-ip', ("Marks, content and links", "Marques, contenu et liens", "العلامات والمحتوى والروابط"), [
  ("The text, structure and original graphics of this site belong to {{ company.brand }} unless a page says otherwise. You may quote short extracts with a link back to the page. Longer reuse needs written permission, which you can ask for through the [contact page](/contact/). Other names, brands and logos that appear belong to their owners and are used only to identify them; their appearance is not an endorsement by them of W5D, nor by W5D of them.",
   "Les textes, la structure et les graphismes originaux de ce site appartiennent à {{ company.brand }}, sauf mention contraire sur une page. Vous pouvez citer de courts extraits avec un lien vers la page. Une réutilisation plus longue exige une autorisation écrite, que vous pouvez demander via la [page de contact](/contact/). Les autres noms, marques et logos qui apparaissent appartiennent à leurs propriétaires et ne servent qu’à les identifier ; leur présence n’est pas une approbation de W5D par eux, ni d’eux par W5D.",
   "نصوص هذا الموقع وبنيته ورسوماته الأصلية ملك لـ{{ company.brand }} ما لم تذكر صفحة غير ذلك. ويجوز لك اقتباس مقاطع قصيرة مع رابط إلى الصفحة. أما إعادة الاستخدام الأطول فتحتاج إذنًا كتابيًا يمكنك طلبه عبر [صفحة الاتصال](/contact/). وسائر الأسماء والعلامات والشعارات الظاهرة ملك لأصحابها وتُستخدم للتعريف بهم فقط؛ وظهورها ليس تزكية منهم لـW5D ولا من W5D لهم."),
  ("We link to outside sites only when they help you check a statement, for example a public registry or an official text. We do not control those sites and we are not responsible for what they contain or for their data practices; read their own notices. If a link we give is broken or has changed in a way that misleads, tell us through the [corrections desk](/trust/corrections/) and we will fix or remove it.",
   "Nous ne renvoyons vers des sites extérieurs que lorsqu’ils vous aident à vérifier une affirmation, par exemple un registre public ou un texte officiel. Nous ne contrôlons pas ces sites et ne répondons ni de leur contenu ni de leurs pratiques de données ; lisez leurs propres mentions. Si un lien que nous donnons est cassé ou a changé de façon trompeuse, dites-le-nous via le [service des corrections](/trust/corrections/) et nous le corrigerons ou le retirerons.",
   "لا نربط بمواقع خارجية إلا حين تعينك على التحقق من قول ما، كسجل عام أو نص رسمي. ولا نتحكم في تلك المواقع ولا نتحمل مسؤولية محتواها ولا ممارساتها في البيانات؛ فاقرأ إشعاراتها الخاصة. وإن كان رابط نذكره معطوبًا أو تغيّر بما يضلل فأخبرنا عبر [مكتب التصويبات](/trust/corrections/) لنصلحه أو نزيله.")]),
 prose('im-law', ("Applicable law and disputes", "Droit applicable et litiges", "القانون المنطبق والنزاعات"), [
  ("The relationship between W5D and its users is governed by Tunisian law, as the [terms](/trust/terms/) explain. This does not remove any mandatory right that a consumer has under the law of the country where they live; where such a right is stronger than what the terms say, the stronger right applies. We prefer to settle a disagreement by talking: write to us first, and we answer in writing within {{ company.response_days }} working days with a reasoned position.",
   "La relation entre W5D et ses utilisateurs est régie par le droit tunisien, comme l’expliquent les [conditions](/trust/terms/). Cela ne supprime aucun droit impératif dont dispose un consommateur selon la loi du pays où il vit ; lorsqu’un tel droit est plus protecteur que ce que disent les conditions, le droit le plus protecteur s’applique. Nous préférons régler un désaccord en parlant : écrivez-nous d’abord, et nous répondons par écrit sous {{ company.response_days }} jours ouvrés avec une position motivée.",
   "تخضع العلاقة بين W5D ومستخدميها للقانون التونسي كما تشرح [الشروط](/trust/terms/). ولا يُسقط هذا أي حق آمر يملكه المستهلك بموجب قانون بلد إقامته؛ وحيث يكون ذلك الحق أقوى مما تقوله الشروط يسري الأقوى. ونفضّل تسوية الخلاف بالحوار: راسلنا أولًا ونجيب كتابةً خلال {{ company.response_days }} أيام عمل بموقف معلَّل."),
  ("If we cannot agree, the competent courts are those the law designates, and a consumer keeps the right to bring a case where the law gives it. Which court is competent in a given case is a legal question that we confirm with a Tunisian lawyer, and we do not pretend to settle it in this notice. Regulatory complaints about personal data may be made to the Tunisian data protection authority; the route is described on the [data rights page](/trust/data-rights/).",
   "Si nous ne parvenons pas à nous entendre, les juridictions compétentes sont celles que désigne la loi, et le consommateur conserve le droit de saisir la juridiction que la loi lui ouvre. Quelle juridiction est compétente dans un cas donné est une question juridique que nous confirmons avec un avocat tunisien, et nous ne prétendons pas la trancher dans ces mentions. Les plaintes réglementaires relatives aux données personnelles peuvent être adressées à l’autorité tunisienne de protection des données ; la voie est décrite sur la page [vos droits](/trust/data-rights/).",
   "وإن لم نتفق فالمحاكم المختصة هي التي يعيّنها القانون، ويحتفظ المستهلك بحق رفع الدعوى حيث يمنحه القانون ذلك. وأي محكمة تختص في حالة بعينها مسألة قانونية نؤكدها مع محامٍ تونسي ولا ندّعي حسمها في هذا الإشعار. ويمكن تقديم الشكاوى التنظيمية المتعلقة بالبيانات الشخصية إلى السلطة التونسية لحماية المعطيات الشخصية؛ والطريق موصوف في صفحة [حقوقك](/trust/data-rights/).")]),
 faq('im-faq', ("Questions about this notice", "Questions sur ces mentions", "أسئلة عن هذا الإشعار"), [
  (("Is W5D a registered company?", "W5D est-elle une société immatriculée ?", "هل W5D شركة مسجّلة؟"), ("Not at the last review ({{ dates.as_of }}). The registration is in progress and the footer states the current legal form on every page. If you are about to pay, read the [status page](/status/) first.", "Pas à la dernière revue ({{ dates.as_of }}). L’immatriculation est en cours et le pied de page indique la forme juridique actuelle sur chaque page. Si vous êtes sur le point de payer, lisez d’abord la [page de statut](/status/).", "ليست كذلك عند آخر مراجعة ({{ dates.as_of }}). التسجيل قيد الإنجاز ويذكر التذييل الشكل القانوني الحالي في كل صفحة. وإن كنت على وشك الدفع فاقرأ [صفحة الحالة](/status/) أولًا.")),
  (("Why is there no postal address?", "Pourquoi n’y a-t-il pas d’adresse postale ?", "لماذا لا يوجد عنوان بريدي؟"), ("The business is run from a home setting by its founder, and publishing a private address would expose a person for no benefit to you. A postal address is given for formal notices on request, and a business address will be published once the business has one.", "L’activité est exercée depuis un cadre domestique par son fondateur, et publier une adresse privée exposerait une personne sans bénéfice pour vous. Une adresse postale est donnée sur demande pour les notifications formelles, et une adresse professionnelle sera publiée dès que l’activité en aura une.", "يُدار النشاط من بيئة منزلية على يد مؤسسه، ونشر عنوان خاص يعرّض شخصًا دون نفع لك. ويُعطى عنوان بريدي للإشعارات الرسمية عند الطلب، وسيُنشر عنوان مهني حين يصير للنشاط عنوان.")),
  (("Who do I write to about my personal data?", "À qui écrire au sujet de mes données personnelles ?", "إلى من أكتب بشأن بياناتي الشخصية؟"), ("To {{ company.privacy_contact }}, or through the form on the [data rights page](/trust/data-rights/). Say what you want to do and we reply in writing within {{ privacy.rights_days }} days.", "À {{ company.privacy_contact }}, ou via le formulaire de la page [vos droits](/trust/data-rights/). Dites ce que vous voulez faire et nous répondons par écrit sous {{ privacy.rights_days }} jours.", "إلى {{ company.privacy_contact }} أو عبر النموذج في صفحة [حقوقك](/trust/data-rights/). قل ما تريد فعله ونرد كتابةً خلال {{ privacy.rights_days }} يومًا.")),
  (("Can I rely on this page in a legal dispute?", "Puis-je m’appuyer sur cette page dans un litige ?", "هل يمكنني الاستناد إلى هذه الصفحة في نزاع قانوني؟"), ("It states how we operate and what we have said to you, and we are bound by what we publish. It is not legal advice to you; for your own case, ask a lawyer in your country.", "Elle dit comment nous opérons et ce que nous vous avons dit, et nous sommes tenus par ce que nous publions. Ce n’est pas un avis juridique pour vous ; pour votre propre cas, consultez un avocat de votre pays.", "تبيّن كيف نعمل وما قلناه لك، ونحن ملزمون بما ننشر. وهي ليست استشارة قانونية لك؛ ولحالتك الخاصة استشر محاميًا في بلدك.")),
  (("How will I know when the legal status changes?", "Comment saurai-je que le statut juridique change ?", "كيف سأعلم بتغير الوضع القانوني؟"), ("The footer and this page change together, and the date of the last review is shown below. Orders already placed keep the terms they were placed under; see the [terms](/trust/terms/).", "Le pied de page et cette page changent ensemble, et la date de la dernière revue est affichée plus bas. Les commandes déjà passées conservent les conditions sous lesquelles elles ont été passées ; voir les [conditions](/trust/terms/).", "يتغير التذييل وهذه الصفحة معًا، ويظهر تاريخ آخر مراجعة أدناه. وتحتفظ الطلبات المقدمة بالشروط التي قُدّمت بموجبها؛ انظر [الشروط](/trust/terms/)."))]),
 prose('im-related', ("Related pages and review", "Pages liées et revue", "صفحات ذات صلة والمراجعة"), [
  ("Read the [terms](/trust/terms/), the [privacy policy](/trust/privacy/), the [cookie policy](/trust/cookies/), the [refund rules](/trust/refunds/), the [advertising policy](/trust/ads-policy/), the [editorial policy](/trust/editorial/) and the [accessibility statement](/trust/accessibility/).",
   "Lisez les [conditions](/trust/terms/), la [politique de confidentialité](/trust/privacy/), la [politique de cookies](/trust/cookies/), les [règles de remboursement](/trust/refunds/), la [politique publicitaire](/trust/ads-policy/), la [politique éditoriale](/trust/editorial/) et la [déclaration d’accessibilité](/trust/accessibility/).",
   "اقرأ [الشروط](/trust/terms/) و[سياسة الخصوصية](/trust/privacy/) و[سياسة الكوكيز](/trust/cookies/) و[قواعد الاسترداد](/trust/refunds/) و[سياسة الإعلانات](/trust/ads-policy/) و[السياسة التحريرية](/trust/editorial/) و[بيان إمكانية الوصول](/trust/accessibility/)."),
  VERIFY]),
 cta_block('im-final', ("A question for the publisher? **Ask in writing.**", "Une question à l’éditeur ? **Posez-la par écrit.**", "سؤال للناشر؟ **اطرحه كتابةً.**"), ("Every message is read by a person and answered within {{ company.response_days }} working days.", "Chaque message est lu par une personne et reçoit une réponse sous {{ company.response_days }} jours ouvrés.", "يقرأ كل رسالة شخص ويُجاب عنها خلال {{ company.response_days }} أيام عمل."),
  [(("Contact the publisher", "Contacter l’éditeur", "اتصل بالناشر"), '/contact/', 'peak', True), (("Live status", "Statut en direct", "الحالة الحية"), '/status/', 'ghost', False)]),
 ])
